import { readFile, writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import { fontSizes, fontWeights, textStyles, lineHeights, lineHeight } from '../apps/ui/src/features/typography/scale.ts';

const path = fileURLToPath(new URL('../apps/ui/src/features/typography/scale.generated.css', import.meta.url));
const sizes = Object.entries(fontSizes);
const output = [
  '/* Generated by scripts/build-typography-scale.mjs. Edit scale.ts. */',
  ':root {',
  ...sizes.map(([name, value]) => `  --font-size-${name}: ${value}rem;`),
  ...sizes.map(([name]) => `  --line-height-${name}: ${lineHeight(name).ratio};`),
  ...Object.entries(textStyles).flatMap(([name, style]) => [
    `  --text-${name}-size: var(--font-size-${style.size});`,
    `  --text-${name}-weight: var(--font-weight-${style.weight});`,
    `  --text-${name}-leading: ${lineHeight(style.size, style.leading).ratio};`,
  ]),
  '}', '', '@theme static {',
  ...Object.entries(lineHeights).map(([name, value]) => `  --leading-${name}: ${value};`),
  ...Object.entries(fontWeights).map(([name, value]) => `  --font-weight-${name}: ${value};`),
  '  --font-weight-bold: var(--font-weight-semibold);',
  '}', '', '@theme inline {',
  ...sizes.flatMap(([name]) => [`  --text-${name}: var(--font-size-${name});`, `  --text-${name}--line-height: var(--line-height-${name});`]),
  '}', '', '@layer components {',
  ...Object.keys(textStyles).map(name => `  .type-${name} { font-size: var(--text-${name}-size); font-weight: var(--text-${name}-weight); line-height: var(--text-${name}-leading); }`),
  '}', '',
].join('\n');
const current = await readFile(path, 'utf8').catch(error => { if (error.code !== 'ENOENT') throw error; return ''; });
if (current !== output) {
  if (process.argv.includes('--check')) throw new Error('Typography scale CSS is stale. Run pnpm typography:build.');
  await writeFile(path, output);
}
console.log(`Typography scale ${process.argv.includes('--check') ? 'checked' : 'generated'}: ${sizes.length} sizes, ${Object.keys(textStyles).length} text styles.`);
